import {localTime} from './remote-state.js';
import {reviewImport} from './import-preview.js';
import {createBackend} from './backend-ui.js';
import {money,paisa,timestamp,normRef,fullRef,importOrders,importStatement,reconcile,decide,exportCSV,receiptHints,demoData,csvCell} from './engine.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const labels={ship:'Ship',hold:'Hold',review:'Review'};
const pill=s=>`<span class="pill ${s}"><i></i>${labels[s]}</span>`;
const when=t=>Number.isFinite(t)?new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Karachi',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(t):'Not readable';
const initials=n=>n.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('');
let state={...demoData(),mode:'demo',view:'results',filter:'all',query:'',results:[],activity:[],epoch:0,error:'',ordersFile:'orders-demo.csv',statementFile:'statement-demo.csv'},busy=false,ocrBusy=false,worker=null,workerPromise=null,activeReview=null,toastTimer;
state.results=reconcile(state);
const content=$('#app-content');
const backend=createBackend({getState:()=>state,setState:value=>{state=value},render,showWorkspace,dispose,toast,ask});
function log(title,detail){state.activity.unshift({title,detail,at:Date.now()});}
log('Demo batch is ready','12 fictional orders, sample receipt fields and a synthetic statement. Matching is computed locally.');
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function download(text,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function ask(title,text,label='Continue'){return new Promise(resolve=>{const d=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;$('#confirm-yes').textContent=label;let done=false;const finish=value=>{if(done)return;done=true;d.close();d.removeEventListener('cancel',cancel);resolve(value);};const cancel=e=>{e.preventDefault();finish(false);};$('#confirm-yes').onclick=()=>finish(true);$('#confirm-cancel').onclick=()=>finish(false);d.addEventListener('cancel',cancel);d.showModal();});}
function dispose(){state.claims.forEach(c=>{if(c.url)URL.revokeObjectURL(c.url);});state.epoch++;if(worker){worker.terminate();worker=null;}workerPromise=null;ocrBusy=false;}
async function fresh(demo=false){if(backend.busy())return toast('Wait for the current server operation.');if(!demo)return backend.newBatch();if(busy||ocrBusy)return toast('Let the current operation finish first.');if(!state.remote&&state.mode==='own'&&(state.orders.length||state.claims.length||state.lines.length)){if(!await ask('Replace this batch?','Your current records and review decisions will be cleared. Export them first if you want to keep them.',demo?'Load demo':'Start fresh'))return;}
  const epoch=state.epoch+1;dispose();state={...(demo?demoData():{orders:[],claims:[],lines:[],coverage:{start:'',end:'',complete:false},referenceVerified:false}),mode:demo?'demo':'own',view:demo?'results':'imports',filter:'all',query:'',results:[],activity:[],epoch,error:'',ordersFile:demo?'orders-demo.csv':'',statementFile:demo?'statement-demo.csv':''};
  if(demo){state.results=reconcile(state);log('Demo loaded','Fictional sample records. This demo does not use a bank or cloud AI.');}else log('New batch created','Records will stay in this browser tab until cleared or reloaded.');
  showWorkspace();
}
function showWorkspace(view){if(view)state.view=view;$('#landing').hidden=true;$('#workspace').hidden=false;document.body.classList.add('workspace-open');location.hash='workspace';render();window.scrollTo(0,0);document.dispatchEvent(new CustomEvent('milaan-visibility'));}
function home(){if(busy||ocrBusy||backend.busy())return toast('Let the current operation finish first.');$('#workspace').hidden=true;$('#landing').hidden=false;document.body.classList.remove('workspace-open');history.replaceState(null,'',location.pathname+location.search);window.scrollTo(0,0);document.dispatchEvent(new CustomEvent('milaan-visibility'));}
function totals(){return {all:state.results.length,ship:state.results.filter(r=>r.status==='ship').length,hold:state.results.filter(r=>r.status==='hold').length,review:state.results.filter(r=>r.status==='review').length};}
function render(){
  const own=state.mode==='own';$('#mode-chip').textContent=own?'YOUR FILES · LOCAL':'SAMPLE DATA';$('#profile-label').innerHTML=own?'Your workspace<small>Browser session</small>':"Ayesha's Studio<small>Demo workspace</small>";
  if(state.remote){$('#mode-chip').textContent=state.remote.is_demo?'SAVED SAMPLE':'SAVED ON SERVER';$('#profile-label').innerHTML=esc(backend.content()?.workspace?.value?.shop_name||backend.profile()?.display_name||'Your workspace')+'<small>Connected account</small>';}
  $('#clear-label').textContent=state.remote?'Delete saved batch':'Clear demo session';
  $('#nav-count').textContent=state.orders.length;$('#crumb').textContent={results:'Reconciliation',imports:'Import center',activity:'Activity log',batches:'Saved batches',settings:'Settings'}[state.view];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
  if(state.view==='batches')backend.batches();else if(state.view==='settings')backend.settings();else if(state.view==='results')renderResults();else if(state.view==='imports')renderImports();else renderActivity();
}
function intro(kicker,title,subtitle,actions=''){return `<div class="page-intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="intro-actions">${actions}</div></div>`;}
function renderResults(){
  const t=totals();let actions=`<button class="btn btn-outline" data-action="export" ${!t.all?'disabled':''}>${icon('download')}Export results</button><button class="btn btn-forest" data-action="reconcile" ${!state.orders.length?'disabled':''}>${icon('spark')}Reconcile batch</button>`;
  let html=intro(state.mode==='demo'?'FRIDAY, 09 OCTOBER 2026 · DEMO BATCH':'YOUR CURRENT BATCH',state.remote?esc(backend.content()?.branding?.value?.hero_title||'A little clarity for your day.'):'A little clarity for your day.',state.mode==='demo'?'Your orders, your payment proofs. Let’s connect the dots.':'Compare your payment claims with your uploaded statement.',actions);
  if(state.mode==='demo')html+=`<div class="demo-notice">${icon('spark')}<span>You’re exploring sample data. Every result below is computed from these sample records.</span><button data-action="new">Use your own files ${icon('arrow')}</button></div>`;
  if(!state.results.length){content.innerHTML=html+`<div class="results-panel empty-state">${icon('file')}<h2>${state.orders.length?'Ready when you are.':'Start with your records.'}</h2><p>${state.orders.length?'Finish importing your statement and payment proofs, then run reconciliation to see the evidence.':'Add an order list, a statement and payment screenshots. Or explore a fictional seller’s day in the demo.'}</p><button class="btn btn-forest" data-view="imports">Go to Import center ${icon('arrow')}</button></div>`;return;}
  const sum=state.orders.reduce((a,o)=>a+o.due,0),safe=state.results.filter(r=>r.status==='ship').reduce((a,r)=>a+r.order.due,0);
  html+=`<div class="stat-grid"><div class="stat-card"><div class="stat-label">Orders in this batch<span class="stat-icon">${icon('file')}</span></div><strong>${t.all}</strong><small>PKR ${money(sum)} in order value</small><div class="stat-meter"><i style="width:100%"></i></div></div><div class="stat-card stat-ship"><div class="stat-label">Ready to ship<span class="stat-icon">${icon('check')}</span></div><strong>${t.ship}</strong><small>PKR ${money(safe)} matched to records</small><div class="stat-meter"><i style="width:${t.ship/t.all*100}%"></i></div></div><div class="stat-card stat-hold"><div class="stat-label">On hold<span class="stat-icon">${icon('clock')}</span></div><strong>${t.hold}</strong><small>Follow up before dispatch</small><div class="stat-meter"><i style="width:${t.hold/t.all*100}%"></i></div></div><div class="stat-card stat-review"><div class="stat-label">Needs your eyes<span class="stat-icon">${icon('search')}</span></div><strong>${t.review}</strong><small>A little human judgment needed</small><div class="stat-meter"><i style="width:${t.review/t.all*100}%"></i></div></div></div>`;
  html+=`<div class="batch-layout"><section class="results-panel"><div class="table-top">${state.remote?'<button class="btn btn-outline btn-small" data-action="allocation-plan">Review payment allocations</button>':''}<h2>Payment reconciliation <span class="count-badge">${t.all} orders</span></h2><label class="search-box">${icon('search')}<input id="search-orders" placeholder="Search orders..." value="${esc(state.query)}" aria-label="Search customers, orders and Transaction ID / Reference number"></label></div><div class="filter-row" role="group" aria-label="Filter results">${['all','ship','hold','review'].map(f=>`<button class="filter-btn ${state.filter===f?'active':''}" data-filter="${f}" aria-pressed="${state.filter===f}">${f==='all'?'All orders':labels[f]}<span class="filter-count">${t[f]}</span></button>`).join('')}</div><label class="field discrepancy-filter">Discrepancy type<select id="discrepancy-filter"><option value="">All discrepancy types</option>${[...new Set(state.results.map(r=>r.code))].sort().map(code=>`<option value="${esc(code)}" ${state.reasonFilter===code?'selected':''}>${esc(code.replaceAll('_',' '))}</option>`).join('')}</select></label><div class="table-wrap"><table><thead><tr><th>CUSTOMER / ORDER</th><th>AMOUNT</th><th class="ref-column">TRANSACTION ID / REFERENCE NUMBER</th><th>DECISION</th></tr></thead><tbody id="results-body"></tbody></table></div><div class="table-footer"><span id="result-count"></span><span><i class="legend-dot"></i> All times in PKT</span></div></section><aside class="batch-side"><div class="batch-info"><div class="panel-kicker">THIS BATCH ${icon('file')}</div><h3 class="batch-name">${state.remote?esc(state.remote.name):state.mode==='demo'?"Ayesha’s Studio<br/>Friday dispatch":'Your reconciliation batch'}</h3><p class="batch-subtitle">${state.mode==='demo'?'Fictional online jewellery shop':'Records saved on your backend'}</p><div class="info-row"><span>Currency</span><b>PKR · Pakistani Rupee</b></div><div class="info-row"><span>Statement</span><b>${state.coverage.complete?'Coverage declared':'Check coverage'}</b></div><div class="info-row"><span>Time zone</span><b>Asia / Karachi</b></div><div class="batch-divider"></div><div class="source-list">${icon('file')}<span>${state.orders.length} orders</span><span>CSV</span></div><div class="source-list">${icon('file')}<span>${state.lines.length} statement lines</span><span>CSV</span></div><div class="source-list">${icon('file')}<span>${state.claims.length} payment claims</span><span>${state.mode==='demo'?'SAMPLE':'SAVED'}</span></div></div><div class="side-tip">${icon('shield')}<h3>A match has a reason.<br/>So does a review.</h3><p>Open any order to see the receipt, the candidate credits and exactly what needs your attention.</p><button data-action="first-review">Explore an exception ${icon('arrow')}</button></div></aside></div>`;
  content.innerHTML=html;renderRows();
}
function renderRows(){const body=$('#results-body');if(!body)return;const q=state.query.toLowerCase(),rows=state.results.filter(r=>(state.filter==='all'||r.status===state.filter)&&(!state.reasonFilter||r.code===state.reasonFilter)&&[r.id,r.order.name,r.claim?.ref,...r.candidates.map(l=>l.ref)].join(' ').toLowerCase().includes(q));
  body.innerHTML=rows.length?rows.map((r,i)=>`<tr tabindex="0" data-order="${esc(r.id)}" aria-label="Review order ${esc(r.id)} for ${esc(r.order.name)}"><td><div class="customer"><span class="avatar tint-${i%3}">${esc(initials(r.order.name))}</span><div><div class="customer-name">${esc(r.order.name)}</div><div class="customer-order">#${esc(r.id.replace(/^#/,''))}${r.decision?' · Manually reviewed':''}</div></div></div></td><td class="amount-cell"><span>Rs</span>${money(r.order.due)}</td><td class="ref-cell ref-column">${esc(r.claim?.ref||'Unreadable / missing')}</td><td><button class="status-button" data-order="${esc(r.id)}" aria-label="Open ${esc(r.order.name)} evidence">${pill(r.status)}${icon('chevron')}</button></td></tr>`).join(''):`<tr><td colspan="4" class="no-results">No orders match this search. Try another name or filter.</td></tr>`;
  $('#result-count').textContent=`Showing ${rows.length} of ${state.results.length} orders`;}
function renderImports(){
  if(state.remote&&state.mode!=='demo')return renderRemoteImports();
  if(state.mode==='demo'){content.innerHTML=intro('EXPLORE FIRST. THEN MAKE IT YOURS.','Your records. One place.','The demo batch is fictional and read-only. Start a fresh batch to import your own files.')+`<div class="results-panel empty-state">${icon('upload')}<h2>Bring your own records.</h2><p>Upload CSV orders and a statement. Add receipt images, check the extracted fields, and run the same matching rules.</p><button class="btn btn-forest" data-action="new">Start a new batch ${icon('arrow')}</button><div style="margin-top:20px"><button class="link-button" data-action="templates">Download sample CSV templates</button></div></div>`;return;}
  content.innerHTML=intro('BROWSER-LOCAL PROCESSING','Bring everything together.','Use the templates below. No financial files are uploaded to a server.')+(state.error?`<div class="validation-error" role="alert">${esc(state.error)}</div>`:'')+`<div class="import-grid"><section class="import-card"><h2><span class="step-label">01</span>Orders</h2><p>Your order references, customer names, amounts due and receiving account IDs.</p><label class="dropzone" data-drop="orders">${icon('upload')}<span>${state.orders.length?'Replace orders CSV':'Choose or drop your orders CSV'}</span><small>CSV · up to 2 MB / 2,000 rows</small><input class="file-input" type="file" accept=".csv,text/csv" data-upload="orders"></label><div class="template-row"><span>Not sure about the format?</span><button data-template="orders">Get the template ↓</button></div><div class="input-status">${state.orders.length?`${icon('check')} ${state.orders.length} orders · ${esc(state.ordersFile)}`:'No orders added yet'}</div></section><section class="import-card"><h2><span class="step-label">02</span>Statement</h2><p>Use the seller’s receiving-account records. Include credits and debits with full timestamps.</p><label class="dropzone" data-drop="statement">${icon('upload')}<span>${state.lines.length?'Replace statement CSV':'Choose or drop your statement CSV'}</span><small>CSV only · PDF support is not included</small><input class="file-input" type="file" accept=".csv,text/csv" data-upload="statement"></label><div class="template-row"><span>One combined statement CSV per batch.</span><button data-template="statement">Get the template ↓</button></div><div class="input-status">${state.lines.length?`${icon('check')} ${state.lines.length} rows · ${esc(state.statementFile)}`:'No statement added yet'}</div></section><section class="import-card wide-card"><h2><span class="step-label">03</span>Statement coverage</h2><p>Use the export’s actual start and end, in Pakistan time. This period must apply to every receiving account in this batch.</p><div class="field-grid"><label class="field">From (PKT)<input type="datetime-local" id="coverage-start" value="${esc(state.coverage.start)}"></label><label class="field">Through (PKT)<input type="datetime-local" id="coverage-end" value="${esc(state.coverage.end)}"></label></div><label class="checkbox-row"><input type="checkbox" id="coverage-complete" ${state.coverage.complete?'checked':''}><span>This export contains all transactions for the stated accounts and period.</span></label><label class="checkbox-row"><input type="checkbox" id="refs-verified" ${state.referenceVerified?'checked':''}><span>I checked that the full sender-side and receiver-side references correspond for these accounts. Otherwise, leave this off and review suggested matches.</span></label><div class="coverage-note">Never infer coverage from the first and last transaction. Claims within 30 minutes of the export end may still be waiting to post.</div></section><section class="import-card wide-card"><div class="upload-header"><h2><span class="step-label">04</span>Payment screenshots</h2><button class="btn btn-outline btn-small" data-action="ocr-all" ${!state.claims.length?'disabled':''}>${icon('spark')}Read all screenshots</button></div><p>Local OCR can help read English text. Check and complete each field yourself before confirming. OCR needs an engine download on first use; your images stay in this browser.</p><label class="dropzone" data-drop="claims">${icon('plus')}<span>Add or drop payment screenshots</span><small>PNG, JPG or WEBP · up to 20 images · 10 MB each</small><input class="file-input" type="file" multiple accept="image/png,image/jpeg,image/webp" data-upload="claims"></label><div class="proof-list">${state.claims.map(proofCard).join('')}</div></section></div><div class="import-run"><p>${state.orders.length} orders · ${state.lines.length} statement rows · ${state.claims.length} payment proofs<br/>Unconfirmed or incomplete claims will be sent to Review.</p><button class="btn btn-forest" data-action="reconcile" ${!state.orders.length||!state.lines.length?'disabled':''}>Reconcile this batch ${icon('arrow')}</button></div>`;
}
function proofCard(c){return `<article class="proof-card" data-proof="${esc(c.id)}"><img class="proof-thumbnail" src="${esc(c.url)}" alt="Payment screenshot ${esc(c.filename)}"><div><div class="proof-top"><span>${esc(c.filename)}</span><div class="proof-actions"><button data-ocr="${esc(c.id)}">${c.ocrStatus||'Read text'}</button><button data-remove="${esc(c.id)}">Remove</button></div></div><div class="proof-fields"><label class="field">Link to order<select data-claim-field="order" data-claim="${esc(c.id)}"><option value="">Choose an order</option>${state.orders.map(o=>`<option value="${esc(o.id)}" ${c.order===o.id?'selected':''}>#${esc(o.id)} · ${esc(o.name)}</option>`).join('')}</select></label><label class="field">Amount (PKR)<input inputmode="decimal" data-claim-field="amount" data-claim="${esc(c.id)}" value="${c.amount?(c.amount/100).toFixed(2):''}" placeholder="3500.00"></label><label class="field">Transaction ID / Reference number<input data-claim-field="ref" data-claim="${esc(c.id)}" value="${esc(c.ref)}" placeholder="Enter the full Transaction ID / Reference number"></label><label class="field">Date & time (PKT)<input type="datetime-local" data-claim-field="at" data-claim="${esc(c.id)}" value="${esc(c.at)}"></label><label class="field">Receiving account<input data-claim-field="account" data-claim="${esc(c.id)}" value="${esc(c.account)}" placeholder="Must match statement"></label><label class="field">Payment status<input data-claim-field="status_text" data-claim="${esc(c.id)}" value="${esc(c.status_text||'')}" placeholder="As shown on receipt"></label><label class="field">Sender name<input data-claim-field="name" data-claim="${esc(c.id)}" value="${esc(c.name)}" placeholder="As shown on screenshot"></label></div><label class="checkbox-row proof-confirm"><input type="checkbox" data-claim-field="confirmed" data-claim="${esc(c.id)}" ${c.confirmed?'checked':''}><span>I checked the payment status, amount, timestamp, account and reference against this screenshot.</span></label>${c.text?`<details class="proof-raw"><summary>View raw OCR text</summary><pre>${esc(c.text)}</pre></details>`:''}</div></article>`;}
function renderActivity(){content.innerHTML=intro('A RECORD OF YOUR DECISIONS','Nothing hidden. Every step recorded.','Imports, reconciliation runs and review decisions for the current batch.',`<button class="btn btn-outline" data-action="audit-export">${icon('download')}Export log</button>`)+`<div class="activity-list">${state.activity.length?state.activity.map(e=>`<article class="activity-item"><div class="event-dot">${icon('check')}</div><div><h3>${esc(e.title)}</h3><p>${esc(e.detail)}</p></div><time>${when(e.at)} PKT</time></article>`).join(''):'<div class="empty-state"><h2>No activity yet.</h2></div>'}</div>`;}
async function run(){
  if(state.remote)return backend.run();
  if(busy||ocrBusy)return toast('Let the current operation finish first.');
  if(!state.orders.length||!state.lines.length)return toast('Add both orders and a statement first.');
  if(state.mode==='own'&&state.claims.some(c=>!c.order||!state.orders.some(o=>o.id===c.order))){state.view='imports';state.error='Link every screenshot to a valid order, or remove it, before reconciling.';render();return;}
  if(state.results.some(r=>r.decision)&&!await ask('Re-run this batch?','A new run replaces the current results and clears manual approvals. Your previous decisions stay in the activity log.','Re-run'))return;
  busy=true;state.view='results';$('#crumb').textContent='Reconciliation';$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='results'));
  content.innerHTML=intro('RECONCILIATION IN PROGRESS','Following the evidence.','Amounts, references, coverage and duplicate claims.')+`<div class="loading-panel" role="status" aria-live="polite"><div class="loading-orb"></div><h2>Connecting claims to credits.</h2><p id="run-step">Checking ${state.orders.length} orders against ${state.lines.length} statement rows...</p><div class="progress-track"><i></i></div></div>`;
  try{const result=reconcile(state);await new Promise(r=>setTimeout(r,document.body.classList.contains('motion-paused')?100:1000));state.results=result;state.filter='all';state.reasonFilter='';state.query='';const t=totals();log('Batch reconciled',`${t.ship} Ship · ${t.hold} Hold · ${t.review} Review. ${state.mode==='demo'?'Sample data.':'Uploaded records; local rules.'}`);}catch(e){state.error=e.message;toast(e.message);}finally{busy=false;render();}
}
async function openReview(id){const r=state.results.find(r=>r.id===id);if(!r)return;activeReview=id;const linked=state.remote?state.claims.filter(c=>c.serverOrder===r.order.serverId||r.allocations?.some(a=>a.claim_id===c.id)):r.claim?[r.claim]:[];const c=r.claim||linked[0];if(state.remote&&c?.hasImage){try{c.url=await backend.image(c);}catch{toast('Receipt preview could not load. Check your session and refresh.');}}const taken=lineId=>state.remote?r.candidates.find(l=>l.id===lineId)?.available===false:state.results.some(x=>x.id!==id&&x.status==='ship'&&x.allocated===lineId);
  $('#review-content').innerHTML=`<div class="drawer-head"><div><h2>Order #${esc(r.id.replace(/^#/,''))}</h2><p>${esc(r.order.name)} · Rs ${money(r.order.due)}</p></div><button class="icon-button" data-close="review-dialog" aria-label="Close evidence review">${icon('close')}</button></div><div class="drawer-body"><div class="review-result">${pill(r.status)}${r.decision?'<span class="count-badge" style="margin-left:8px">MANUALLY REVIEWED</span>':''}<p>${esc(r.decision?r.decision.reason:r.reason)}</p></div><div class="evidence-columns"><section><div class="evidence-heading">PAYMENT PROOF <small>${state.mode==='demo'?'SAMPLE':linked.length>1?'FIRST OF '+linked.length+' RECEIPTS':'UPLOADED'}</small></div>${c?.url?`<img class="review-photo" src="${esc(c.url)}" alt="Payment screenshot for order ${esc(r.id)}">`:c?`<div class="sample-receipt"><span>${icon('check')}</span><p>Payment screenshot</p><strong>Rs ${money(c.amount)}</strong><dl><div><dt>From</dt><dd>${esc(c.name)}</dd></div><div><dt>Transaction ID / Reference number</dt><dd>${esc(c.ref||'Unreadable')}</dd></div><div><dt>At</dt><dd>${when(timestamp(c.at))}</dd></div><div><dt>To</dt><dd>${esc(c.account)}</dd></div></dl><small>FICTIONAL RECEIPT · DEMO ONLY</small></div>`:'<div class="no-credit">No screenshot has been linked.</div>'}</section><section><div class="evidence-heading">STATEMENT CANDIDATES</div>${r.candidates.length?r.candidates.map(l=>`<label class="candidate"><span class="candidate-top"><input type="radio" name="candidate" value="${esc(l.id)}" ${taken(l.id)?'disabled':''} ${r.allocated===l.id||r.candidates.length===1&&!taken(l.id)?'checked':''}><span>${esc(l.name)}</span><strong>Rs ${money(l.amount)}</strong></span><small>${esc(l.ref)}<br/>${when(l.time)} PKT · ${taken(l.id)?'Already used by another order':'Available credit'}</small></label>`).join(''):'<div class="no-credit">No matching statement credit.<br/>Check coverage or request clearer proof.</div>'}</section></div><div class="checks"><h3>What the records tell us</h3>${checkRow('Order amount',`Rs ${money(r.order.due)}`)}${checkRow('Screenshot amount',c?.amount?`Rs ${money(c.amount)}`:'Missing',c?.amount!==r.order.due)}${checkRow('Reference',c?.ref||'Unreadable',!fullRef(c?.ref))}${checkRow('Receiving account',c?.account||'Missing',c?.account!==r.order.account)}${state.remote?checkRow('Allocated funding',`Rs ${money(r.paid||0)} · outstanding Rs ${money(r.outstanding||0)}`):''}${checkRow('Automatic decision',labels[r.machine],r.machine!=='ship')}${checkRow('Reason code',r.code,true)}${(r.evidence||[]).filter(e=>e.check==='pakistani_name_similarity').map(e=>checkRow('AiCON name similarity',`${e.order_name} ↔ ${e.matched_name} · ${Math.round(e.score*100)}% similarity (not payment confidence)`)).join('')}</div><form class="decision-form" id="decision-form"><h3>Your review decision</h3><label class="field">Reason for this decision<textarea id="decision-reason" required minlength="5" maxlength="500" placeholder="e.g. Customer confirmed they paid from a family member’s account.">${esc(r.decision?.reason||'')}</textarea></label><div class="decision-actions"><button class="btn btn-forest" type="submit" name="decision" value="ship" ${!r.candidates.some(l=>!taken(l.id)&&l.amount===r.order.due)||['DUPLICATE_CREDIT','REVERSAL'].includes(r.code)?'disabled':''}>${icon('check')}Confirm match</button><button class="btn btn-outline" type="submit" name="decision" value="hold">Keep on hold</button><button class="btn btn-outline" type="submit" name="decision" value="review">Needs review</button></div><p class="decision-warning">A manual match needs a selected, unallocated statement credit. Your decision and reason are recorded. Choosing Hold or Review releases current reservations; use allocation review to keep partial funding reserved. No payment or shipping action is sent.</p><div id="decision-error" class="validation-error" role="alert" hidden></div></form><div class="message-area"><div>Customer message draft<button data-action="copy-message">Copy text</button></div><p id="customer-message">${esc(customerMessage(r))}</p></div></div>`;
  if(!$('#review-dialog').open)$('#review-dialog').showModal();
}
function checkRow(a,b,w=false){return `<div class="check-row"><span>${esc(a)}</span><b class="${w?'uncertain':''}">${esc(b)}</b></div>`;}
function customerMessage(r){if(state.remote){const custom=backend.content()?.messages?.value?.[r.status==='ship'?'matched':'review'];if(custom)return custom;}if(r.status==='ship')return `Hi ${r.order.name.split(' ')[0]}, thank you! We’ve matched your payment of Rs ${money(r.order.due)} to our records for order #${r.id.replace(/^#/,'')}. We’ll proceed with the order.`;return `Hi ${r.order.name.split(' ')[0]}, we’re checking the payment for order #${r.id.replace(/^#/,'')}. Could you please share the full Transaction ID / Reference number and a clear payment screenshot? We haven’t been able to confirm the match from our current records yet. Thank you!`;}
async function importFile(kind,files){
  if(state.remote){try{return await backend.upload(kind,files);}catch(e){state.error=e.message;toast(e.message);render();return;}}
  if(busy||ocrBusy)return toast('Let the current operation finish first.');if(state.mode!=='own')return;
  if(state.results.length&&!await ask('Update source records?','Changing inputs will clear current results and approvals. Previous decisions remain in the activity log.','Update records'))return;
  const epoch=state.epoch;busy=true;state.error='';
  try{
    if(kind==='claims'){
      if(state.claims.length+files.length>20)throw Error('Use up to 20 screenshots in a batch.');
      const valid=[...files];for(const f of valid){if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error(`${f.name}: choose a PNG, JPG or WEBP image.`);if(f.size>10*1024*1024)throw Error(`${f.name}: image exceeds 10 MB.`);}
      for(const f of valid){
        const bitmap=await createImageBitmap(f);if(bitmap.width*bitmap.height>25_000_000){bitmap.close();throw Error(`${f.name}: image exceeds 25 megapixels.`);}
        const canvas=document.createElement('canvas');const scale=Math.min(1,2400/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
        const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.92));if(!blob)throw Error('Could not read this image.');
        const hash=await crypto.subtle.digest('SHA-256',await f.arrayBuffer());if(state.epoch!==epoch)return;
        const digest=Array.from(new Uint8Array(hash),v=>v.toString(16).padStart(2,'0')).join('');
        state.claims.push({id:crypto.randomUUID(),order:'',name:'',amount:null,ref:'',at:'',account:'',status_text:'',confirmed:false,mode:'manual',filename:f.name,digest,url:URL.createObjectURL(blob)});
      }
      log('Screenshots added',`${files.length} images decoded and re-encoded locally. Original metadata is not retained in the working image.`);
    }else{
      const f=await reviewImport(files[0],kind,{local:true});if(!f)return;
      const text=await f.text(),parsed=kind==='orders'?importOrders(text):importStatement(text);if(state.epoch!==epoch)return;
      if(kind==='orders'){state.orders=parsed;state.ordersFile=f.name;state.claims.forEach(c=>{if(!parsed.some(o=>o.id===c.order))c.order='';c.confirmed=false;});log('Orders imported',`${parsed.length} orders from ${f.name}.`);}
      else{state.lines=parsed;state.statementFile=f.name;state.coverage.complete=false;state.referenceVerified=false;log('Statement imported',`${parsed.length} rows from ${f.name}. Coverage and reference checks must be declared again.`);}
    }
    state.results=[];toast('Added. Check the details below.');
  }catch(e){state.error=e.message;toast(e.message);}finally{busy=false;if(state.epoch===epoch)render();}
}
function getOCR(){
  if(window.Tesseract)return Promise.resolve(window.Tesseract);if(window.milaanOcrLoad)return window.milaanOcrLoad;
  window.milaanOcrLoad=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js';s.crossOrigin='anonymous';const timer=setTimeout(()=>reject(Error('OCR engine download timed out. Enter the details manually or try again.')),30000);s.onload=()=>{clearTimeout(timer);window.Tesseract?resolve(window.Tesseract):reject(Error('OCR engine did not start.'));};s.onerror=()=>{clearTimeout(timer);reject(Error('OCR engine could not download. You can enter the details manually.'));};document.head.append(s);}).catch(error=>{window.milaanOcrLoad=null;throw error;});return window.milaanOcrLoad;
}
async function readOCR(ids){
  if(state.remote)return backend.read(ids);
  if(busy||ocrBusy)return toast('Let the current operation finish first.');if(state.mode!=='own')return;
  if(state.results.length&&!await ask('Read the screenshot again?','New text suggestions clear current results and approvals. Check the new fields before reconciling.','Read text'))return;
  ocrBusy=true;const epoch=state.epoch;let current='';
  try{
    toast('Loading the local text reader. First use can take a moment.');
    const T=await getOCR();let timeout;
    workerPromise=T.createWorker('eng',1,{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@6.0.0',logger:m=>{if(m.status==='recognizing text'){const b=$(`[data-ocr="${current}"]`);if(b)b.textContent=`Reading ${Math.round(m.progress*100)}%`;}}});
    worker=await Promise.race([workerPromise,new Promise((_,reject)=>timeout=setTimeout(()=>reject(Error('OCR initialization timed out. Enter the fields manually.')),60000))]);clearTimeout(timeout);
    for(const id of ids){current=id;const claim=state.claims.find(c=>c.id===id);if(!claim)continue;const button=$(`[data-ocr="${id}"]`);if(button){button.disabled=true;button.textContent='Reading...';}
      let readTimer;let result;
      try{result=await Promise.race([worker.recognize(claim.url),new Promise((_,reject)=>readTimer=setTimeout(()=>reject(Error('This image took too long to read. Try a smaller image or enter its details.')),60000))]);}finally{clearTimeout(readTimer);}
      if(state.epoch!==epoch)return;const hints=receiptHints(result.data.text);claim.text=result.data.text;claim.mode='ocr';claim.ocrStatus='Read again';claim.confirmed=false;
      if(!claim.amount&&hints.amount){try{claim.amount=paisa(hints.amount);}catch{}}if(!claim.ref)claim.ref=hints.ref;
      state.results=[];log('Screenshot text read',`${claim.filename}: OCR text is a suggestion. The amount, reference and time require human confirmation.`);renderImports();
    }
    toast('Text read. Check the amount and reference, then enter the correct date and time.');
  }catch(e){toast(e.message||'Text reading failed. Enter the screenshot details manually.');state.error=e.message;renderImports();}
  finally{const p=workerPromise;if(worker)await worker.terminate().catch(()=>{});else if(p)p.then(w=>w.terminate()).catch(()=>{});worker=null;workerPromise=null;ocrBusy=false;}
}
function template(kind){const orders='order_ref,customer_name,amount_due,account_id,currency\r\n1042,Hira Khan,3500.00,shop-wallet,PKR\r\n1043,Sana Malik,4200.00,shop-wallet,PKR\r\n';const statement='posted_at,direction,amount,counterparty,transaction_id,account_id,currency\r\n2026-10-09T14:22,CREDIT,3500.00,Hira Khan,MLN778810,shop-wallet,PKR\r\n2026-10-09T16:05,CREDIT,4200.00,Sana Malik,MLN778811,shop-wallet,PKR\r\n';download(kind==='orders'?orders:statement,`milaan-${kind}-template.csv`);}
function scenario(kind){const data={match:{amount:'3,500',ref:'MLN778810',status:'ship',title:'Same amount. Same reference.',body:'A unique credit in the seller’s statement aligns with the payment claim and the order. That is a reason to move forward.',tag:'Transaction ID / Reference number + exact amount',label:'Hira Khan · Order #1042'},missing:{amount:'2,800',ref:'MLN940031',status:'hold',title:'“Successful” is not the full story.',body:'The statement covers this period, but no matching credit appears. Hold the order and follow up. This is not a fraud verdict.',tag:'No credit in supplied records',label:'Usman Tariq · Order #1044'},duplicate:{amount:'2,500',ref:'MLN778814',status:'review',title:'One payment. Two different claims.',body:'The same reference is linked to two orders. Milaan asks for a review so one credit cannot silently pay for both.',tag:'Same reference used twice',label:'Orders #1049 + #1050'}}[kind];$('#scenario-stage').innerHTML=`<div class="scenario-record"><div class="record-kicker">ILLUSTRATIVE PAYMENT CLAIM</div><div class="record-value">Rs ${data.amount}<span class="pill ship"><i></i>Successful</span></div><div class="record-meta"><span>${data.label}</span><span>${data.ref}</span></div></div><div class="scenario-arrow">→</div><div class="scenario-outcome">${pill(data.status)}<h3>${data.title}</h3><p>${data.body}</p></div>`;$$('[data-scenario]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.scenario===kind)));}
document.addEventListener('click',async e=>{
  const b=e.target.closest('button,a,[data-order]');if(!b)return;
  try{
    if(b.dataset.close){$('#'+b.dataset.close).close();return;}
    if(b.dataset.scenario){scenario(b.dataset.scenario);return;}
    if(b.dataset.action){e.preventDefault();const action=b.dataset.action;
      if(action==='home')return home();if(action==='demo')return await fresh(true);if(action==='workspace')return backend.open();if(action==='new')return await fresh(false);if(action==='help')return $('#help-dialog').showModal();
      if(action==='reconcile')return await run();
      if(action==='export'){if(!state.results.length)return;if(state.remote)return await backend.exportResults();download(exportCSV(state.results,state.mode==='demo'?'FICTIONAL_DEMO':'UPLOADED_RECORDS'),'milaan-reconciliation.csv');log('Results exported',`${state.results.length} order outcomes downloaded as CSV.`);toast('Reconciliation CSV exported.');return;}
      if(action==='audit-export'){download(JSON.stringify({mode:state.mode,events:state.activity},null,2),'milaan-activity-log.json','application/json');return;}
      if(action==='first-review'){const row=state.results.find(r=>r.status==='review')||state.results[0];if(row)await openReview(row.id);return;}
      if(action==='copy-message'){const text=$('#customer-message').textContent;try{await navigator.clipboard.writeText(text);toast('Copied. Review the message before sending it.');}catch{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents($('#customer-message'));selection.removeAllRanges();selection.addRange(range);toast('Text selected. Use Copy on your device.');}return;}
      if(action==='templates'){template('orders');setTimeout(()=>template('statement'),400);return;}
      if(action==='ocr-all')return await readOCR(state.claims.map(c=>c.id));
      if(action==='clear'){if(state.remote)return await backend.clear();if(busy||ocrBusy)return toast('Let the current operation finish first.');if(await ask('Clear this session?','This removes all imported records, images, results and the activity log from this tab. Download your export first.','Clear session')){dispose();const epoch=state.epoch;state={orders:[],claims:[],lines:[],coverage:{start:'',end:'',complete:false},referenceVerified:false,mode:'demo',view:'imports',filter:'all',query:'',results:[],activity:[],epoch,error:'',ordersFile:'',statementFile:''};render();toast('Session cleared.');}return;}
    }
    if(b.dataset.view){if(busy||ocrBusy||backend.busy())return toast('Let the current operation finish first.');state.view=b.dataset.view;render();window.scrollTo(0,0);return;}
    if(b.dataset.filter){state.filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter===state.filter);x.setAttribute('aria-pressed',String(x.dataset.filter===state.filter));});renderRows();return;}
    if(b.dataset.order){await openReview(b.dataset.order);return;}
    if(b.dataset.template){template(b.dataset.template);return;}
    if(b.dataset.ocr){await readOCR([b.dataset.ocr]);return;}
    if(b.dataset.remove){if(state.remote){if(await ask('Remove this receipt?','This deletes the uploaded receipt and its extracted fields.','Remove'))await backend.remove(b.dataset.remove);return;}if(busy||ocrBusy)return toast('Let the current operation finish first.');if(await ask('Remove this screenshot?','Current reconciliation results will be cleared. You can add this image again.','Remove')){const c=state.claims.find(c=>c.id===b.dataset.remove);if(c?.url)URL.revokeObjectURL(c.url);state.claims=state.claims.filter(c=>c.id!==b.dataset.remove);state.results=[];log('Screenshot removed',c?.filename||'Payment proof');render();}}
  }catch(error){toast(error.message||'Something went wrong. Please try again.');}
});
document.addEventListener('input',e=>{if(e.target.id==='search-orders'){state.query=e.target.value;renderRows();}});
document.addEventListener('change',async e=>{
  const el=e.target;if(el.id==='discrepancy-filter'){state.reasonFilter=el.value;renderRows();return;}if(el.dataset.upload&&el.files.length){const files=[...el.files];el.value='';await importFile(el.dataset.upload,files);return;}
  if(el.dataset.claimField){if(state.remote){try{backend.edit(el);}catch(error){toast(error.message);render();}return;}if(busy||ocrBusy){toast('Wait for the current operation before editing.');render();return;}const c=state.claims.find(c=>c.id===el.dataset.claim);if(!c)return;const f=el.dataset.claimField;try{
    if(f==='amount'){c.amount=el.value?paisa(el.value):null;el.setCustomValidity('');}else if(f==='confirmed'){if(el.checked&&(!c.amount||!Number.isFinite(timestamp(c.at))||!c.account||!c.order)){el.checked=false;throw Error('Set the order, amount, receiving account and timestamp first.');}c.confirmed=el.checked;}else c[f]=el.value;
    if(f==='order'){const o=state.orders.find(o=>o.id===c.order);c.account=o?.account||'';c.name=c.name||o?.name||'';}
    if(f!=='confirmed')c.confirmed=false;state.results=[];state.error='';if(f==='order')renderImports();else{const checkbox=$(`[data-claim-field="confirmed"][data-claim="${c.id}"]`);if(checkbox)checkbox.checked=c.confirmed;}
  }catch(error){if(f==='amount'){c.amount=null;c.confirmed=false;const checkbox=$(`[data-claim-field="confirmed"][data-claim="${c.id}"]`);if(checkbox)checkbox.checked=false;state.results=[];el.setCustomValidity(error.message);el.reportValidity();}toast(error.message);}return;}
  if(el.id==='statement-account'){
    state.statementAccount=el.value;const existing=state.statements.find(s=>s.account_id===el.value);
    state.coverage=existing?{start:localTime(existing.coverage_start),end:localTime(existing.coverage_end),complete:existing.complete}:{start:'',end:'',complete:false};
    state.referenceVerified=existing?.references_verified||false;
    // Keep the focused input in the DOM: replacing it on blur can discard the next edit.
    for(const field of ['start','end']){const input=$(`[data-coverage="${field}"]`);if(input)input.value=state.coverage[field];}
    for(const field of ['complete','references']){const input=$(`[data-coverage="${field}"]`);if(input)input.checked=field==='complete'?state.coverage.complete:state.referenceVerified;}
    return;
  }
  if(el.dataset.coverage){if(el.dataset.coverage==='start'||el.dataset.coverage==='end')state.coverage[el.dataset.coverage]=el.value;else if(el.dataset.coverage==='complete')state.coverage.complete=el.checked;else state.referenceVerified=el.checked;return;}
  if(['coverage-start','coverage-end','coverage-complete','refs-verified'].includes(el.id)){if(el.id==='coverage-start')state.coverage.start=el.value;if(el.id==='coverage-end')state.coverage.end=el.value;if(el.id==='coverage-complete')state.coverage.complete=el.checked;if(el.id==='refs-verified')state.referenceVerified=el.checked;state.results=[];}
});
document.addEventListener('submit',async e=>{if(e.target.id!=='decision-form')return;e.preventDefault();try{const status=e.submitter?.value||'review',line=$('input[name="candidate"]:checked')?.value,reason=$('#decision-reason').value;if(state.remote){await backend.decision(state.results.find(r=>r.id===activeReview),status,line,reason);$('#review-dialog').close();return;}state.results=decide(state.results,activeReview,status,line,reason);log(`Order #${activeReview}: ${labels[status]}`,reason);$('#review-dialog').close();render();toast('Decision saved with your reason.');}catch(error){$('#decision-error').hidden=false;$('#decision-error').textContent=error.message;}});
document.addEventListener('keydown',e=>{const row=e.target.closest('tr[data-order]');if(row&&e.key==='Enter'){e.preventDefault();openReview(row.dataset.order).catch(error=>toast(error.message));}if(e.target.matches('[data-scenario]')&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const tabs=$$('[data-scenario]'),i=tabs.indexOf(e.target),n=(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].focus();scenario(tabs[n].dataset.scenario);}});
['dragover','dragleave','drop'].forEach(type=>document.addEventListener(type,e=>{const zone=e.target.closest('[data-drop]');if(!zone)return;e.preventDefault();zone.classList.toggle('dragover',type==='dragover');if(type==='drop')importFile(zone.dataset.drop,[...e.dataTransfer.files]);}));
window.addEventListener('beforeunload',e=>{if(state.claims.some(c=>c.dirty)||(!state.remote&&state.mode==='own'&&(state.orders.length||state.claims.length||state.lines.length))){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{if(location.hash==='#workspace')showWorkspace();else if(!$('#workspace').hidden)home();});
scenario('match');if(location.hash==='#workspace')showWorkspace();

function renderRemoteImports(){
  const locked=!!state.remote.latest_run_id,account=state.statementAccount||state.orders.find(o=>!state.statements.some(s=>s.account_id===o.account))?.account||state.orders[0]?.account||'';
  const options=[...new Set(state.orders.map(o=>o.account))].map(a=>`<option value="${esc(a)}"></option>`).join('');
  content.innerHTML=intro('YOUR SAVED RECORDS','Bring everything together.',esc(state.remote.name),`<button class="btn btn-outline" data-action="refresh-batch">Refresh saved data</button>`)+
    (state.error?`<div class="validation-error" role="alert">${esc(state.error)}</div>`:'')+
    (locked?`<div class="demo-notice"><span>Source records are locked after reconciliation. Reset this batch to edit inputs; current credit allocations will be released.</span><button data-action="edit-inputs">Reset and edit →</button></div>`:'')+
    `<div class="import-grid"><section class="import-card"><h2><span class="step-label">01</span>Orders</h2><p>Upload order references, names, PKR amounts and receiving-account IDs.</p><label class="dropzone">${icon('upload')}<span>${state.orders.length?'Orders saved':'Choose orders CSV'}</span><small>UTF-8 CSV · 2 MB · 2,000 rows</small><input class="file-input" type="file" accept=".csv,text/csv" data-upload="orders" ${locked||state.orders.length?'disabled':''}></label><div class="template-row"><span>${state.orders.length} saved orders</span><button data-template="orders">Get template ↗</button></div></section>
    <section class="import-card"><h2>Saved statements</h2><p>One CSV per receiving account. Add another account’s statement below.</p>${state.statements.length?state.statements.map(s=>`<div class="saved-statement"><b>${esc(s.account_id)}</b><small>${esc(s.filename)} · ${s.complete?'Complete period declared':'Coverage unconfirmed'}</small><button class="link-button" data-remove-statement="${esc(s.id)}" ${locked?'disabled':''}>Remove statement</button></div>`).join(''):'<p>No statements yet.</p>'}<button class="link-button" data-template="statement">Download statement template</button></section>
    <section class="import-card wide-card"><h2><span class="step-label">02</span>Import a statement</h2><p>Set the account and actual export period before choosing the CSV. Times below are Pakistan time.</p><fieldset class="plain-fieldset" ${locked?'disabled':''}><div class="field-grid"><label class="field">Receiving account<input id="statement-account" list="receiving-accounts" value="${esc(account)}" placeholder="Same account_id as the orders"><datalist id="receiving-accounts">${options}</datalist></label><label class="field">From (PKT)<input type="datetime-local" data-coverage="start" value="${esc(state.coverage.start)}"></label><label class="field">Through (PKT)<input type="datetime-local" data-coverage="end" value="${esc(state.coverage.end)}"></label></div><label class="checkbox-row"><input type="checkbox" data-coverage="complete" ${state.coverage.complete?'checked':''}><span>This export includes all transactions for this account and period.</span></label><label class="checkbox-row"><input type="checkbox" data-coverage="references" ${state.referenceVerified?'checked':''}><span>I verified that the sender’s Transaction ID / Reference number corresponds to the number on the receiving statement.</span></label><label class="dropzone">${icon('upload')}<span>Choose this account’s statement CSV</span><small>CSV only · PDF layouts need conversion</small><input class="file-input" type="file" accept=".csv,text/csv" data-upload="statement"></label></fieldset></section>
    <section class="import-card wide-card"><div class="upload-header"><h2><span class="step-label">03</span>Payment receipts</h2><button class="btn btn-outline btn-small" data-action="ocr-all" ${locked||!state.claims.length?'disabled':''}>${icon('spark')}Read pending with AI</button></div><p>Select the correct order before uploading. Enter receipt details yourself, or request Gemini reading only after agreeing to send that image to Google. Always confirm the result against the screenshot.</p><fieldset class="plain-fieldset" ${locked?'disabled':''}><label class="field">These new screenshots belong to<select id="upload-order"><option value="">Choose an order</option>${state.orders.map(o=>`<option value="${esc(o.serverId)}">${esc(o.id)} · ${esc(o.name)} · PKR ${money(o.due)}</option>`).join('')}</select></label><label class="dropzone">${icon('plus')}<span>Choose payment screenshots</span><small>JPEG, PNG or WEBP · 10 MB each · 100 receipts per batch</small><input class="file-input" type="file" multiple accept="image/png,image/jpeg,image/webp" data-upload="claims"></label><div class="proof-list">${state.claims.map(remoteProofCard).join('')}</div></fieldset></section></div><div class="import-run"><p>${state.orders.length} orders · ${state.lines.length} statement lines · ${state.claims.length} receipts<br>Save each edited receipt before running reconciliation.</p><button class="btn btn-forest" data-action="reconcile" ${!state.orders.length||!state.lines.length?'disabled':''}>Reconcile this batch →</button></div>`;
  backend.hydrate();
}
function remoteProofCard(c){return `<article class="proof-card"><img class="proof-thumbnail" data-server-image="${esc(c.id)}" src="${esc(c.url||'favicon.svg')}" alt="Receipt ${esc(c.filename)}"><div><div class="proof-top"><span>${esc(c.filename)} · ${esc(c.order)}</span><div class="proof-actions"><button data-ocr="${esc(c.id)}">Read with AI</button><button data-remove="${esc(c.id)}">Remove</button></div></div><p class="input-status">${esc(c.ocrStatus)} · ${esc(c.account)}</p><div class="proof-fields"><label class="field">Amount (PKR)<input inputmode="decimal" data-claim-field="amount" data-claim="${esc(c.id)}" value="${c.amount?(c.amount/100).toFixed(2):''}"></label><label class="field">Transaction ID / Reference number<input data-claim-field="ref" data-claim="${esc(c.id)}" value="${esc(c.ref)}"></label><label class="field">Date and time (PKT)<input type="datetime-local" data-claim-field="at" data-claim="${esc(c.id)}" value="${esc(c.at)}"></label><label class="field">Payment status<input data-claim-field="status_text" data-claim="${esc(c.id)}" value="${esc(c.status_text||'')}" placeholder="As shown on receipt"></label><label class="field">Sender name<input data-claim-field="name" data-claim="${esc(c.id)}" value="${esc(c.name)}"></label></div><label class="checkbox-row"><input type="checkbox" data-claim-field="confirmed" data-claim="${esc(c.id)}" ${c.confirmed?'checked':''}><span>Allow these fields for matching. Verify them against the original receipt.</span></label><button class="btn btn-outline btn-small" data-save-claim="${esc(c.id)}">Save receipt fields</button>${c.text?`<details class="proof-raw"><summary>Inspect AI reads</summary><pre>${esc(c.text)}</pre></details>`:''}</div></article>`;}

backend.restore();
